import { Difficulty, QuestionItem } from './types';

// Helper for Game 9: ¡Continúa la historia!
function mkG9(level: Difficulty, rows: [string, string, string, string][]): QuestionItem[] {
  return rows.map(([prompt, promptHy, sample, rubricHint], idx) => ({
    id: `g9_${level}_${idx + 1}`,
    gameId: 'continua_historia',
    level,
    prompt,
    promptHy,
    answer: sample,
    rubricHint,
    answerDetail: 'Juego creativo: el profesor evalúa gramática, lógica y vocabulario en español.',
  }));
}

// Helper for Game 10: ¡Duelo de preguntas!
function mkG10(level: Difficulty, rows: [string, string, string][]): QuestionItem[] {
  return rows.map(([prompt, promptHy, sample], idx) => ({
    id: `g10_${level}_${idx + 1}`,
    gameId: 'duelo_preguntas',
    level,
    prompt,
    promptHy,
    answer: sample,
    answerDetail: 'Responde con una frase completa y natural en español.',
  }));
}

// Helper for Game 11: ¡Categorías explosivas!
function mkG11(level: Difficulty, rows: [string, string, string, string][]): QuestionItem[] {
  return rows.map(([category, categoryHy, letter, examples], idx) => ({
    id: `g11_${level}_${idx + 1}`,
    gameId: 'categorias_explosivas',
    level,
    prompt: `${category} — Letra ${letter}`,
    promptHy: `${categoryHy} — Տառը՝ ${letter}`,
    category,
    categoryHy,
    letter,
    answer: examples,
    answerDetail: 'Se acepta cualquier palabra válida en español de esta categoría que empiece por esa letra.',
  }));
}

// Helper for Game 12: ¡Misión España!
function mkG12(level: Difficulty, rows: [string, string, string, string, string, string[]][]): QuestionItem[] {
  return rows.map(([location, locationHy, prompt, promptHy, answer, altAnswers], idx) => ({
    id: `g12_${level}_${idx + 1}`,
    gameId: 'mision_espana',
    level,
    location,
    locationHy,
    prompt,
    promptHy,
    answer,
    altAnswers,
    answerDetail: 'Se aceptan otras expresiones educadas y naturales para esta situación.',
  }));
}

